import logging
from .creality_config import *

class GCodeMove:

    def __init__(self, config):
        self.config = config
        self.printer = printer = config.get_printer()
        printer.register_event_handler("klippy:ready", self._handle_ready)
        printer.register_event_handler("klippy:shutdown", self._handle_shutdown)
        printer.register_event_handler("toolhead:set_position", self.reset_last_position)
        printer.register_event_handler("toolhead:manual_move", self.reset_last_position)
        printer.register_event_handler("gcode:command_error", self.reset_last_position)
        printer.register_event_handler("extruder:activate_extruder", self._handle_activate_extruder)
        printer.register_event_handler("homing:home_rails_end", self._handle_home_rails_end)
        self.is_printer_ready = False
        self.gcode = gcode = printer.lookup_object("gcode")
        handlers = [
         "G1", "G20", "G21",
         "M82", "M83", "G90", "G91", "G92", "M220", "M221",
         "SET_GCODE_OFFSET", "RESET_GCODE_OFFSET", "SAVE_GCODE_STATE", "RESTORE_GCODE_STATE", "QMODE", "QMODE_EXIT"]
        for cmd in handlers:
            func = getattr(self, "cmd_" + cmd)
            desc = getattr(self, "cmd_" + cmd + "_help", None)
            gcode.register_command(cmd, func, False, desc)

        gcode.register_command("G0", self.cmd_G1)
        gcode.register_command("M114", self.cmd_M114, True)
        gcode.register_command("GET_POSITION", (self.cmd_GET_POSITION), True, desc=(self.cmd_GET_POSITION_help))
        gcode.register_command("CLEAN_EXTUDE", (self.cmd_CLEAN_EXTUDE), True, desc=(self.cmd_CLEAN_EXTUDE_help))
        self.Coord = gcode.Coord
        self.absolute_coord = self.absolute_extrude = True
        self.base_position = [0.0, 0.0, 0.0, 0.0]
        self.last_position = [0.0, 0.0, 0.0, 0.0]
        self.homing_position = [0.0, 0.0, 0.0, 0.0]
        self.speed = 25.0
        self.speed_factor = 0.016666666666666666
        self.extrude_factor = 1.0
        self.quiet_mode = False
        self.speed_avoids = []
        self.toolhead = None
        self.saved_states = {}
        self.move_transform = self.move_with_transform = self.move_arc_with_transform = None
        self.position_with_transform = lambda: [0.0, 0.0, 0.0, 0.0]
        self.variable_safe_z = 2

    def _handle_ready(self):
        self.is_printer_ready = True
        self.toolhead = self.printer.lookup_object("toolhead")
        self.speed_avoids = self.toolhead.get_speed_avoid()
        if self.move_transform is None:
            toolhead = self.toolhead
            self.move_with_transform = toolhead.move
            self.move_arc_with_transform = toolhead.move_arc
            self.position_with_transform = toolhead.get_position
        self.reset_last_position()

    def _handle_shutdown(self):
        if not self.is_printer_ready:
            return
        self.is_printer_ready = False
        logging.info("gcode state: absolute_coord=%s absolute_extrude=%s base_position=%s last_position=%s homing_position=%s speed_factor=%s extrude_factor=%s speed=%s", self.absolute_coord, self.absolute_extrude, self.base_position, self.last_position, self.homing_position, self.speed_factor, self.extrude_factor, self.speed)

    def _handle_activate_extruder(self):
        self.reset_last_position()
        self.extrude_factor = 1.0
        self.base_position[3] = self.last_position[3]

    def _handle_home_rails_end(self, homing_state, rails):
        self.reset_last_position()
        for axis in homing_state.get_axes():
            self.base_position[axis] = self.homing_position[axis]

    def set_move_transform(self, transform, force=False):
        if self.move_transform is not None:
            if not force:
                raise self.printer.config_error("G-Code move transform already specified")
            old_transform = self.move_transform
            if old_transform is None:
                old_transform = self.printer.lookup_object("toolhead", None)
            self.move_transform = transform
            self.move_with_transform = transform.move
            if hasattr(transform, "move_arc"):
                self.move_arc_with_transform = transform.move_arc
            else:
                toolhead = self.printer.lookup_object("toolhead")
                self.move_arc_with_transform = toolhead.move_arc
            self.position_with_transform = transform.get_position
            return old_transform

    def _get_gcode_position(self):
        p = [lp - bp for lp, bp in zip(self.last_position, self.base_position)]
        p[3] /= self.extrude_factor
        return p

    def _get_gcode_speed(self):
        return self.speed / self.speed_factor

    def _get_gcode_speed_override(self):
        return self.speed_factor * 60.0

    def get_status(self, eventtime=None):
        move_position = self._get_gcode_position()
        return {'speed_factor':(self._get_gcode_speed_override)(), 
         'speed':(self._get_gcode_speed)(), 
         'extrude_factor':self.extrude_factor, 
         'absolute_coordinates':self.absolute_coord, 
         'absolute_extrude':self.absolute_extrude, 
         'homing_origin':(self.Coord)(*self.homing_position), 
         'position':(self.Coord)(*self.last_position), 
         'gcode_position':(self.Coord)(*move_position), 
         'qmode_status':self.quiet_mode}

    def reset_last_position(self):
        if self.is_printer_ready:
            self.last_position = self.position_with_transform()

    def cmd_G_move(self, gcmd, IJ, clockwise, is_arc=False):
        params = gcmd.get_command_parameters()
        try:
            for (pos, axis) in enumerate("XYZ"):
                if axis in params:
                    v = float(params[axis])
                    if not self.absolute_coord:
                        self.last_position[pos] += v
                    else:
                        self.last_position[pos] = v + self.base_position[pos]

            if "E" in params:
                v = float(params["E"]) * self.extrude_factor
                if not (self.absolute_coord and self.absolute_extrude):
                    self.last_position[3] += v
                else:
                    self.last_position[3] = v + self.base_position[3]
            if "F" in params:
                gcode_speed = float(params["F"])
                if gcode_speed <= 0.0:
                    raise gcmd.error("Invalid speed in '%s'" % (
                     gcmd.get_commandline(),))
                self.speed = gcode_speed * self.speed_factor
                if self.quiet_mode:
                    self.speed *= self.toolhead.get_quiet_speed_ratio()
        except ValueError as e:
            try:
                raise gcmd.error("Unable to parse move '%s'" % (
                 gcmd.get_commandline(),))
            finally:
                e = None
                del e

        else:
            for speed_avoid in self.speed_avoids:
                if not speed_avoid[0] < self.speed < speed_avoid[1]:
                    self.speed = speed_avoid[2]

            if is_arc:
                self.move_arc_with_transform(self.last_position, self.speed, IJ, clockwise)
            else:
                self.move_with_transform(self.last_position, self.speed)

    def cmd_G1(self, gcmd):
        self.cmd_G_move(gcmd, None, None, False)

    def cmd_G20(self, gcmd):
        raise gcmd.error("Machine does not support G20 (inches) command")

    def cmd_G21(self, gcmd):
        pass

    def cmd_M82(self, gcmd):
        self.absolute_extrude = True

    def cmd_M83(self, gcmd):
        self.absolute_extrude = False

    def cmd_G90(self, gcmd):
        self.absolute_coord = True

    def cmd_G91(self, gcmd):
        self.absolute_coord = False

    def cmd_G92(self, gcmd):
        offsets = [gcmd.get_float(a, None) for a in "XYZE"]
        for (i, offset) in enumerate(offsets):
            if offset is not None:
                if i == 3:
                    offset *= self.extrude_factor
                self.base_position[i] = self.last_position[i] - offset

        if offsets == [None, None, None, None]:
            self.base_position = list(self.last_position)

    def cmd_M114(self, gcmd):
        p = self._get_gcode_position()
        gcmd.respond_raw("X:%.3f Y:%.3f Z:%.3f E:%.3f" % tuple(p))

    def cmd_M220(self, gcmd):
        value = gcmd.get_float("S", 100.0, above=0.0) / 6000.0
        self.speed = self._get_gcode_speed() * value
        self.speed_factor = value

    def cmd_M221(self, gcmd):
        new_extrude_factor = gcmd.get_float("S", 100.0, above=0.0) / 100.0
        last_e_pos = self.last_position[3]
        e_value = (last_e_pos - self.base_position[3]) / self.extrude_factor
        self.base_position[3] = last_e_pos - e_value * new_extrude_factor
        self.extrude_factor = new_extrude_factor

    cmd_SET_GCODE_OFFSET_help = "Set a virtual offset to g-code positions"

    def cmd_SET_GCODE_OFFSET(self, gcmd):
        move_delta = [
         0.0, 0.0, 0.0, 0.0]
        for (pos, axis) in enumerate("XYZE"):
            offset = gcmd.get_float(axis, None)
            if offset is None:
                offset = gcmd.get_float(axis + "_ADJUST", None)
                if offset is None:
                    pass
                else:
                    offset += self.homing_position[pos]
            delta = offset - self.homing_position[pos]
            move_delta[pos] = delta
            self.base_position[pos] += delta
            self.homing_position[pos] = offset

        if gcmd.get_int("MOVE", 0):
            speed = gcmd.get_float("MOVE_SPEED", (self.speed), above=0.0)
            for (pos, delta) in enumerate(move_delta):
                self.last_position[pos] += delta

            self.move_with_transform(self.last_position, speed)

    def cmd_RESET_GCODE_OFFSET(self, gcmd):
        self.base_position = [
         0.0, 0.0, 0.0, 0.0]
        self.homing_position = [0.0, 0.0, 0.0, 0.0]

    cmd_SAVE_GCODE_STATE_help = "Save G-Code coordinate state"

    def cmd_QMODE(self, gcmd):
        if self.quiet_mode:
            gcmd.respond_info("Current in quiet mode")
            return
        self.quiet_mode = True
        self.speed *= self.toolhead.get_quiet_speed_ratio()
        self.gcode.run_script_from_command("QMODE_EXTRAS")

    def cmd_QMODE_EXIT(self, gcmd):
        if not self.quiet_mode:
            gcmd.respond_info("Current not in quiet mode")
            return
        self.quiet_mode = False
        self.speed /= self.toolhead.get_quiet_speed_ratio()
        self.gcode.run_script_from_command("QMODE_EXTRAS_EXIT")

    def cmd_SAVE_GCODE_STATE(self, gcmd):
        state_name = gcmd.get("NAME", "default")
        self.saved_states[state_name] = {'absolute_coord':self.absolute_coord, 
         'absolute_extrude':self.absolute_extrude, 
         'base_position':list(self.base_position), 
         'last_position':list(self.last_position), 
         'homing_position':list(self.homing_position), 
         'speed':self.speed, 
         'speed_factor':self.speed_factor,  'extrude_factor':self.extrude_factor}

    cmd_RESTORE_GCODE_STATE_help = "Restore a previously saved G-Code state"

    def cmd_RESTORE_GCODE_STATE(self, gcmd):
        state_name = gcmd.get("NAME", "default")
        state = self.saved_states.get(state_name)
        if state is None:
            raise gcmd.error("Unknown g-code state: %s" % (state_name,))
        self.absolute_coord = state["absolute_coord"]
        self.absolute_extrude = state["absolute_extrude"]
        self.base_position = list(state["base_position"])
        self.homing_position = list(state["homing_position"])
        self.speed = state["speed"]
        self.speed_factor = state["speed_factor"]
        self.extrude_factor = state["extrude_factor"]
        e_diff = self.last_position[3] - state["last_position"][3]
        self.base_position[3] += e_diff
        if gcmd.get_int("MOVE", 0):
            speed = gcmd.get_float("MOVE_SPEED", (self.speed), above=0.0)
            self.last_position[:3] = state["last_position"][:3]
            self.move_with_transform(self.last_position, speed)

    cmd_GET_POSITION_help = "Return information on the current location of the toolhead"

    def cmd_GET_POSITION(self, gcmd):
        toolhead = self.printer.lookup_object("toolhead", None)
        if toolhead is None:
            raise gcmd.error("Printer not ready")
        kin = toolhead.get_kinematics()
        steppers = kin.get_steppers()
        mcu_pos = " ".join(["%s:%d" % (s.get_name(), s.get_mcu_position()) for s in steppers])
        cinfo = [(s.get_name(), s.get_commanded_position()) for s in steppers]
        stepper_pos = " ".join(["%s:%.6f" % (a, v) for a, v in cinfo])
        kinfo = zip("XYZ", kin.calc_position(dict(cinfo)))
        kin_pos = " ".join(["%s:%.6f" % (a, v) for a, v in kinfo])
        toolhead_pos = " ".join(["%s:%.6f" % (a, v) for a, v in zip("XYZE", toolhead.get_position())])
        gcode_pos = " ".join(["%s:%.6f" % (a, v) for a, v in zip("XYZE", self.last_position)])
        base_pos = " ".join(["%s:%.6f" % (a, v) for a, v in zip("XYZE", self.base_position)])
        homing_pos = " ".join(["%s:%.6f" % (a, v) for a, v in zip("XYZ", self.homing_position)])
        gcmd.respond_info("mcu: %s\nstepper: %s\nkinematic: %s\ntoolhead: %s\ngcode: %s\ngcode base: %s\ngcode homing: %s" % (
         mcu_pos, stepper_pos, kin_pos, toolhead_pos,
         gcode_pos, base_pos, homing_pos))

    cmd_CX_RESTORE_GCODE_STATE_help = "Restore a previously saved G-Code state"

    def cmd_CX_RESTORE_GCODE_STATE(self, print_info, XYZE):
        toolhead = self.printer.lookup_object("toolhead")
        gcode_macro = self.printer.lookup_object("gcode_macro_cmd")
        power_less = self.printer.lookup_object("creality_power_less")
        fs = self.printer.get_features()
        extras_extrusion = 0.0
        if fs.has_set(PL_PROCESS_EXTRUSION):
            extras_extrusion = 80.0
        safe_x_pos, safe_y_pos = gcode_macro.safe_x_pos, gcode_macro.safe_y_pos
        extrude_resume = gcode_macro.safe_extrude + extras_extrusion
        self.variable_safe_z = 2.0
        logging.info("CX_RESTORE_GCODE_STATE start")
        try:
            max_accel = toolhead.get_max_accel()
            min_cruise_ratio = toolhead.min_cruise_ratio
            square_corner_velocity = toolhead.square_corner_velocity
            state = {'absolute_extrude':True, 
             'file_position':0, 
             'extrude_factor':1.0, 
             'speed_factor':0.016, 
             'homing_position':[
              0.0, 0.0, 0.0, 0.0], 
             'last_position':[
              0.0, 0.0, 0.0, 0.0], 
             'speed':25.0, 
             'file_path':"", 
             'base_position':[
              0.0, 0.0, 0.0, -0.0], 
             'absolute_coord':True, 
             'fan_state':{},  'variable_z_safe_pause':0, 
             'M204':"", 
             'filament_used':0, 
             'last_print_duration':0, 
             'pressure_advance':"", 
             'smooth_time':"", 
             'max_accel':max_accel, 
             'min_cruise_ratio':min_cruise_ratio, 
             'square_corner_velocity':square_corner_velocity, 
             'max_velocity':0, 
             'max_accel_to_decel':0}
            base_position_e = -1
            state["file_position"] = print_info.get("file_position", 0)
            state["base_position"] = [0.0, 0.0, 0.0,
             print_info.get("base_position_e", -1)]
            base_position_e = print_info.get("base_position_e", -1)
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE base_position_e:%s" % base_position_e)
            state["file_path"] = print_info.get("file_path", "")
            state["absolute_extrude"] = print_info.get("absolute_extrude", True)
            state["absolute_coord"] = print_info.get("absolute_coord", True)
            state["fan_state"] = print_info.get("fan_state", {})
            state["variable_z_safe_pause"] = print_info.get("variable_z_safe_pause", 0)
            state["M204"] = print_info.get("M204", "")
            state["SET_GCODE_OFFSET"] = print_info.get("SET_GCODE_OFFSET", 0)
            state["pressure_advance"] = print_info.get("pressure_advance", "")
            state["smooth_time"] = print_info.get("smooth_time", "")
            state["max_accel"] = print_info.get("max_accel", max_accel)
            state["min_cruise_ratio"] = print_info.get("min_cruise_ratio", min_cruise_ratio)
            state["square_corner_velocity"] = print_info.get("square_corner_velocity", square_corner_velocity)
            state["last_position"] = [XYZE["X"], XYZE["Y"],
             XYZE["Z"], XYZE["E"] + base_position_e]
            state["speed"] = print_info.get("speed", 25)
            state["speed_factor"] = print_info.get("speed_factor", 0.016)
            state["extrude_factor"] = print_info.get("extrude_factor", 1)
            state["max_velocity"] = print_info.get("max_velocity", 0)
            state["max_accel_to_decel"] = print_info.get("max_accel_to_decel", 0)
            state["homing_position"] = list(print_info.get("homing_position", [0.0, 0.0, 0.0, 0.0]))
            state["base_position"] = list(print_info.get("base_position", [0.0, 0.0, 0.0, -0.0]))
            state["align_z"] = print_info.get("align_z", 0.0)
            power_loss_z = state["last_position"][2]
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE state:%s" % str(state))
            gcode = self.printer.lookup_object("gcode")
            always_up_frist = True
            if power_less.print_data["passive_z_offset"] > 0.001:
                state["last_position"][2] = state["last_position"][2] - power_less.print_data["passive_z_offset"]
                always_up_frist = False
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE before G28 X Y self.last_position:%s" % str(self.last_position))
            if state["last_position"][2] < 3:
                self.variable_safe_z = 5
            if print_info["z_safe_index"] == 1:
                logging.info("SET_KINEMATIC_POSITION safe_z=%s" % (state["last_position"][2] + self.variable_safe_z))
                gcode.run_script_from_command("SET_KINEMATIC_POSITION z=%s" % (state["last_position"][2] + self.variable_safe_z))
            else:
                logging.info("SET_KINEMATIC_POSITION z=%s" % state["last_position"][2])
                gcode.run_script_from_command("SET_KINEMATIC_POSITION z=%s" % state["last_position"][2])
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE G1 Z%s F3000" % (state["last_position"][2] + self.variable_safe_z))
            power_less.print_data["passive_z_offset"] = self.variable_safe_z
            if always_up_frist:
                gcode.run_script_from_command("G1 Z%s F3000" % (state["last_position"][2] + self.variable_safe_z))
            power_less.print_data["z_safe_index"] = 1
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE z_safe_index:%s" % power_less.print_data["z_safe_index"])
            logging.info("G28 X Y")
            if fs.has_set(PL_PROCESS_ZERO):
                gcode.run_script_from_command("G28 X Y")
                logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE after G28 X Y self.last_position:%s" % str(self.last_position))
                gcode.run_script_from_command("M84 X Y")
                gcode.run_script_from_command("G4 P5000")
            if fs.has_set(ENDSTOP_ALIGN_Z):
                gcode.run_script_from_command("G28 X Y V%.5f" % state["align_z"])
            elif fs.has_set(PL_PROCESS_KEEP_Z):
                gcode.run_script_from_command("G28 X Y K")
            else:
                gcode.run_script_from_command("G28 X Y")
            logging.info("G0 X%s Y%s F6000" % (safe_x_pos, safe_y_pos))
            gcode.run_script_from_command("G0 X%s Y%s F6000" % (safe_x_pos, safe_y_pos))
            logging.info("M106 P0 S255")
            gcode.run_script_from_command("M106 P0 S255")
            logging.info("M106 P2 S255")
            extruder = float(print_info.get("extruder", 201.0))
            gcode.run_script_from_command("M106 P2 S255")
            logging.info("M109 S%s" % extruder)
            gcode.run_script_from_command("M109 S%s" % extruder)
            logging.info("G4 P500")
            gcode.run_script_from_command("G4 P500")
            logging.info("G1 E%s F3000" % extrude_resume)
            gcode.run_script_from_command("G1 E%s F600" % extrude_resume)
            logging.info("G4 P6000")
            gcode.run_script_from_command("G4 P6000")
            self.absolute_coord = state["absolute_coord"]
            self.absolute_extrude = state["absolute_extrude"]
            self.base_position = list(state["base_position"])
            self.homing_position = list(state["homing_position"])
            self.speed_factor = state["speed_factor"]
            self.extrude_factor = state["extrude_factor"]
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE base_position:%s" % str(self.base_position))
            if fs.has_set(PL_PROCESS_EXTRUSION):
                extras_extrusion = 5.0
            else:
                extras_extrusion = 1.0
            e_diff = self.last_position[3] - state["last_position"][3] - 0.7 + extras_extrusion
            self.base_position[3] += e_diff
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE self.last_position[3]:%s, state['last_position'][3]:%s, e_diff:%s,                          base_position[3]:%s" % (
             self.last_position[3], state["last_position"][3], e_diff, self.base_position[3]))
            x = self.last_position[0]
            y = self.last_position[1]
            z = state["last_position"][2] + self.variable_safe_z + state["variable_z_safe_pause"]
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE self.last_position[2]:%s, state['last_position'][2]:%s, self.variable_safe_z:%s,                 state['variable_z_safe_pause']:%s" % (
             self.last_position[2], state["last_position"][2], self.variable_safe_z, state["variable_z_safe_pause"]))
            toolhead = self.printer.lookup_object("toolhead")
            if not fs.has_set(PL_PROCESS_SKIP_BED_MESH):
                if self.config.has_section("z_align"):
                    gcode.run_script_from_command("BED_MESH_CLEAR")
                    z_align = self.printer.lookup_object("z_align")
                    gcode = self.printer.lookup_object("gcode")
                    gcmd = gcode.create_gcode_command("", "", {})
                    z_align.cmd_ZDOWN(gcmd)
                    logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE BED_MESH_PROFILE LOAD='default'")
                    gcode.run_script_from_command('BED_MESH_PROFILE LOAD="default"')
                    now_pos = toolhead.get_position()
                    logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE after cmd_ZDOWN now_pos:%s" % str(now_pos))
                    toolhead.set_position([
                     now_pos[0], now_pos[1], now_pos[2], self.last_position[3]],
                      homing_axes=(2, ))
                else:
                    if power_loss_z <= 1:
                        logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE BED_MESH_PROFILE LOAD='default'")
                        gcode.run_script_from_command('BED_MESH_PROFILE LOAD="default"')
                    offset_value = 0
                    logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE toolhead.set_position:%s" % str([
                     x, y, z + offset_value, self.last_position[3]]))
                    toolhead.set_position([x, y, z + offset_value, self.last_position[3]], homing_axes=(2, ))
            self.last_position[:3] = state["last_position"][:3]
            self.last_position[2] = z
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE G1 X%s Y%s F3000" % (state["last_position"][0], state["last_position"][1]))
            gcode.run_script_from_command("G1 X%s Y%s F3000" % (state["last_position"][0], state["last_position"][1]))
            if not fs.has_set(PL_PROCESS_SKIP_BED_MESH):
                logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE state['speed']:%s" % state["speed"])
                self.speed = state["speed"]
                speed = min(int(self.speed), 50)
                self.move_with_transform(self.last_position, speed)
            gcode.run_script_from_command("M400")
            power_less.print_data["z_safe_index"] = 0
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE z_safe_index:%s" % power_less.print_data["z_safe_index"])
            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE M400")
            gcode.run_script_from_command("M400")
            if state["M204"]:
                logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE SET M204 S%s" % state["M204"])
                gcode.run_script_from_command("M204 S%s" % state["M204"])
            if state["fan_state"]:
                logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE fan fan_state:%s" % str(state["fan_state"]))
                for key in state["fan_state"]:
                    logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE fan set fan:%s#" % str(state["fan_state"].get(key, "")))
                    gcode.run_script_from_command(state["fan_state"].get(key, ""))

            try:
                reactor = self.printer.get_reactor()
                EXCLUDE_OBJECT_DEFINE = print_info.get("EXCLUDE_OBJECT_DEFINE", [])
                EXCLUDE_OBJECT = print_info.get("EXCLUDE_OBJECT", [])
                for obj in EXCLUDE_OBJECT_DEFINE:
                    reactor.pause(reactor.monotonic() + 0.001)
                    name = obj["name"]
                    center = obj["center"]
                    polygon = obj["polygon"]
                    center_str = "%.4f,%.4f" % (center[0], center[1])
                    polygon_str = "[" + ",".join(["[%.4f,%.4f]" % (point[0], point[1]) for point in polygon]) + "]"
                    gcode_command = "EXCLUDE_OBJECT_DEFINE NAME=%s CENTER=%s POLYGON=%s" % (
                     name, center_str, polygon_str)
                    gcode.run_script_from_command(gcode_command)
                    logging.info("EXCLUDE_OBJECT_DEFINE %s" % gcode_command)

                for obj in EXCLUDE_OBJECT:
                    reactor.pause(reactor.monotonic() + 0.001)
                    gcode.run_script_from_command("EXCLUDE_OBJECT NAME=%s" % obj)
                    logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE EXCLUDE_OBJECT NAME=%s" % obj)

                gcode.run_script_from_command("M400")
            except Exception as err:
                try:
                    logging.exception("RESTORE EXCLUDE_OBJECT err:%s" % err)
                finally:
                    err = None
                    del err

            else:
                try:
                    if state["SET_GCODE_OFFSET"] != -5:
                        if state["SET_GCODE_OFFSET"] > 0:
                            params = "-%.3f" % state["SET_GCODE_OFFSET"]
                        elif state["SET_GCODE_OFFSET"] < 0:
                            params = "%.3f" % abs(state["SET_GCODE_OFFSET"])
                        else:
                            params = "0"
                        gcode.run_script_from_command("SET_GCODE_OFFSET Z_ADJUST=%s MOVE=0" % params)
                        gcode.run_script_from_command("Z_OFFSET_APPLY_PROBE")
                        gcode.run_script_from_command("M400")
                        logging.info("power_loss SET_GCODE_OFFSET Z_ADJUST:-%s MOVE=0" % state["SET_GCODE_OFFSET"])
                except Exception as err:
                    try:
                        logging.error("RESTORE SET_GCODE_OFFSET err:%s" % err)
                    finally:
                        err = None
                        del err

                else:
                    if state["pressure_advance"]:
                        gcode.run_script_from_command("M400")
                        if state["smooth_time"]:
                            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE SET pressure_advance:%s smooth_time:%s#" % (state["pressure_advance"], state["smooth_time"]))
                            gcode.run_script_from_command("SET_PRESSURE_ADVANCE ADVANCE=%s SMOOTH_TIME=%s" % (state["pressure_advance"], state["smooth_time"]))
                        else:
                            logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE SET pressure_advance:%s smooth_time:%s#" % state["pressure_advance"])
                            gcode.run_script_from_command("SET_PRESSURE_ADVANCE ADVANCE=%s" % state["pressure_advance"])
                    toolhead.set_max_accel(state["max_accel"])
                    toolhead.set_max_velocity(state["max_velocity"])
                    toolhead.set_max_accel_to_decel(state["max_accel_to_decel"])
                    toolhead.min_cruise_ratio = state["min_cruise_ratio"]
                    toolhead.square_corner_velocity = state["square_corner_velocity"]
                    logging.info("power_loss max_accel=%s min_cruise_ratio=%s square_corner_velocity=%s" % (
                     toolhead.get_max_accel(),
                     toolhead.min_cruise_ratio,
                     toolhead.square_corner_velocity))
                    logging.info("power_loss cmd_CX_RESTORE_GCODE_STATE done")
        except Exception as err:
            try:
                logging.exception("cmd_CX_RESTORE_GCODE_STATE err:%s" % err)
            finally:
                err = None
                del err

    cmd_CLEAN_EXTUDE_help = "Return information on the current location of the toolhead"

    def cmd_CLEAN_EXTUDE(self, gcmd):
        try:
            gcode = self.printer.lookup_object("gcode")
            power_less = self.printer.lookup_object("creality_power_less")
            clean_right_pos_x = power_less.clean_right_pos_x
            clean_left_pos_x = power_less.clean_left_pos_x
            clean_right_pos_y = power_less.clean_right_pos_y
            clean_left_pos_y = power_less.clean_left_pos_y
            clean_velocity = power_less.clean_velocity
            if clean_left_pos_x:
                if clean_left_pos_y:
                    if clean_right_pos_x:
                        if clean_right_pos_y:
                            if clean_velocity:
                                gcode.run_script_from_command("G0 X%.2f Y%.2f F%.2f" % (clean_right_pos_x, clean_right_pos_y, clean_velocity))
                                gcode.run_script_from_command("G0 X%.2f Y%.2f F%.2f" % (clean_left_pos_x, clean_left_pos_y, clean_velocity))
                                gcode.run_script_from_command("G1 E%s F3000" % 100)
                                gcode.run_script_from_command("M400")
                                gcode.run_script_from_command("M106 S255")
                                gcode.run_script_from_command("M400")
                                logging.info("M400")
                                for i in range(3):
                                    gcode.run_script_from_command("G0 X%.2f Y%.2f F%.2f" % (
                                     clean_right_pos_x, clean_right_pos_y, clean_velocity))
                                    gcode.run_script_from_command("G0 X%.2f Y%.2f F%.2f" % (
                                     clean_left_pos_x, clean_left_pos_y, clean_velocity))

                                gcode.run_script_from_command("M400")
                                logging.info("M400")
        except Exception as err:
            try:
                logging.exception("cmd_CLEAN_EXTUDE err:%s" % err)
            finally:
                err = None
                del err


def load_config(config):
    return GCodeMove(config)

